create table if not exists public.staff_coach_relationships (user_id uuid not null references auth.users(id) on delete cascade,coach_id uuid not null references public.college_coaches(id) on delete cascade,college_id uuid references public.colleges(id) on delete cascade,relationship_rating smallint check (relationship_rating between 1 and 5),notes text,next_step text,last_contact_date date,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),primary key(user_id,coach_id));create table if not exists public.staff_recruiting_interactions (id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id) on delete cascade,college_id uuid references public.colleges(id) on delete cascade,coach_id uuid references public.college_coaches(id) on delete cascade,type text not null,channel text,occurred_at timestamptz not null default now(),source text not null default 'manual',subject text,note text);create index if not exists staff_recruiting_interactions_user_coach_idx on public.staff_recruiting_interactions(user_id,coach_id,occurred_at desc);create table if not exists public.organization_college_perspectives (organization_id uuid not null references public.organizations(id) on delete cascade,college_id uuid not null references public.colleges(id) on delete cascade,communication smallint check (communication between 1 and 5),recruiting_experience smallint check (recruiting_experience between 1 and 5),organization_relationship smallint check (organization_relationship between 1 and 5),follow_through smallint check (follow_through between 1 and 5),overall_experience smallint check (overall_experience between 1 and 5),notes text,updated_by uuid references auth.users(id) on delete set null default auth.uid(),created_at timestamptz not null default now(),updated_at timestamptz not null default now(),primary key(organization_id,college_id));alter table public.staff_coach_relationships enable row level security;alter table public.staff_recruiting_interactions enable row level security;alter table public.organization_college_perspectives enable row level security;drop policy if exists staff_coach_relationships_self on public.staff_coach_relationships;create policy staff_coach_relationships_self on public.staff_coach_relationships for all using (user_id=auth.uid()) with check (user_id=auth.uid());drop policy if exists staff_recruiting_interactions_self on public.staff_recruiting_interactions;create policy staff_recruiting_interactions_self on public.staff_recruiting_interactions for all using (user_id=auth.uid()) with check (user_id=auth.uid());drop policy if exists organization_college_perspectives_staff_select on public.organization_college_perspectives;create policy organization_college_perspectives_staff_select on public.organization_college_perspectives for select using (exists(select 1 from public.organization_user_roles r where r.organization_id=organization_college_perspectives.organization_id and r.user_id=auth.uid() and r.status='active' and r.role in ('admin','advisor')) or exists(select 1 from public.organization_members m where m.organization_id=organization_college_perspectives.organization_id and m.user_id=auth.uid() and m.status='active' and m.role::text in ('owner','admin','advisor')));drop policy if exists organization_college_perspectives_staff_insert on public.organization_college_perspectives;create policy organization_college_perspectives_staff_insert on public.organization_college_perspectives for insert with check (exists(select 1 from public.organization_user_roles r where r.organization_id=organization_college_perspectives.organization_id and r.user_id=auth.uid() and r.status='active' and r.role in ('admin','advisor')) or exists(select 1 from public.organization_members m where m.organization_id=organization_college_perspectives.organization_id and m.user_id=auth.uid() and m.status='active' and m.role::text in ('owner','admin','advisor')));drop policy if exists organization_college_perspectives_staff_update on public.organization_college_perspectives;create policy organization_college_perspectives_staff_update on public.organization_college_perspectives for update using (exists(select 1 from public.organization_user_roles r where r.organization_id=organization_college_perspectives.organization_id and r.user_id=auth.uid() and r.status='active' and r.role in ('admin','advisor')) or exists(select 1 from public.organization_members m where m.organization_id=organization_college_perspectives.organization_id and m.user_id=auth.uid() and m.status='active' and m.role::text in ('owner','admin','advisor'))) with check (exists(select 1 from public.organization_user_roles r where r.organization_id=organization_college_perspectives.organization_id and r.user_id=auth.uid() and r.status='active' and r.role in ('admin','advisor')) or exists(select 1 from public.organization_members m where m.organization_id=organization_college_perspectives.organization_id and m.user_id=auth.uid() and m.status='active' and m.role::text in ('owner','admin','advisor')));